package cn.bidcheck.verification.engine;

import cn.bidcheck.verification.facts.TableStructure;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.*;
import org.junit.jupiter.api.Test;
import static cn.bidcheck.verification.engine.VerificationTypes.*;
import static org.junit.jupiter.api.Assertions.*;

class NativePdfTableBindingTest {
    record Fixture(EvidenceCorpus corpus,List<Map<String,Object>> cells,String id) {}
    Fixture fixture(){String id=SourceBoundRecordNormalizationTest.id(),prefix=id.substring(0,13),suffix=id.substring(13);String text="本项目人员配置\n姓名 测试甲 年龄 35\n职称 工程师 身份证号 "+prefix+" 拟在本合同任职 项目负责人\n"+suffix+"\n毕业学校 测试学院";EvidenceCorpus corpus=new PersonnelCountRoleTest().corpus(text);List<Map<String,Object>> cells=new ArrayList<>();
        cells.add(cell(corpus,"name-label",1,1,"姓名",true,List.of(),List.of("姓名")));cells.add(cell(corpus,"name",1,2,"测试甲",false,List.of("name-label"),List.of("测试甲")));
        cells.add(cell(corpus,"id-label",2,3,"身份证号",true,List.of(),List.of("身份证号")));cells.add(cell(corpus,"id",2,4,prefix+"\n"+suffix,false,List.of("id-label"),List.of(prefix,suffix)));
        cells.add(cell(corpus,"role-label",2,5,"拟在本合同任职",true,List.of(),List.of("拟在本合同任职")));cells.add(cell(corpus,"role",2,6,"项目负责人",false,List.of("role-label"),List.of("项目负责人")));return new Fixture(corpus,cells,id);
    }
    Map<String,Object> cell(EvidenceCorpus corpus,String id,int row,int col,String text,boolean header,List<String> headers,List<String> fragments){Source s=corpus.all.get(0);String page=s.evidence().quote();List<Map<String,Object>> refs=new ArrayList<>();int cursor=0;for(String part:fragments){int start=page.indexOf(part,cursor);assertTrue(start>=0);refs.add(linked("text",part,"start",start,"end",start+part.length()));cursor=start+part.length();}return linked("kind","TABLE_CELL","cellId",id,"spanId",id,"source","PDFBOX_NATIVE_TABLE","documentId",s.evidence().documentId(),"documentHash",s.documentHash(),"documentVersion",1,"locationType","PAGE","location",1,"tableId","grid","tableType","KEY_VALUE","row",row,"column",col,"rowSpan",1,"columnSpan",1,"text",text,"header",header,"headerCellIds",headers,"coordinateSpace","PDF_DISPLAY_POINTS_TOP_LEFT","pageWidth",700,"pageHeight",800,"bbox",List.of(col*80,row*40,col*80+70,row*40+35),"sourceFragments",refs);}
    List<Map<String,Object>> sources(Fixture f){return LayoutBinding.sources(role(f),f.corpus.byId);}
    Fact role(Fixture f){return new Fact("role","PERSON_ROLE","项目负责人","姓名","测试甲","测试甲","","","CURRENT_PROJECT",f.corpus.all.stream().map(Source::id).toList(),Map.of("cellIds",List.of("name","id","role")));}
    @Test void splitNativeCellIgnoresInterleavedOtherColumnTextAndBindsExplicitKeyValueRecord(){var f=fixture();assertFalse(f.corpus.all.get(0).evidence().quote().contains(f.id));var result=TableStructure.analyze("测试甲",List.of("name","id","role"),f.cells,sources(f));assertTrue(result.valid(),result.toString());assertEquals("项目负责人",result.rows().get(0).fields().get("ROLE"));assertTrue(result.rows().get(0).strongIdentity());var verified=new ProofVerifier(f.corpus.byId).verify(new ObjectMapper().valueToTree(Map.of("facts",List.of(role(f)))),f.corpus.all,f.cells);assertTrue(verified.rejected().isEmpty(),verified.rejected().toString());assertEquals(1,verified.facts().size());}
    @Test void fragmentOffsetOrPageGeometryCannotBeInvented(){for(boolean offset:List.of(true,false)){var f=fixture();var value=f.cells.stream().filter(c->c.get("cellId").equals("id")).findFirst().orElseThrow();if(offset){var fragments=RuleEvaluator.maps(value.get("sourceFragments"));var modified=new ArrayList<Map<String,Object>>();for(var part:fragments){Map<String,Object> p=new LinkedHashMap<>(part);p.put("start",((Number)p.get("start")).intValue()+1);p.put("end",((Number)p.get("end")).intValue()+1);modified.add(p);}value.put("sourceFragments",modified);}else value.put("bbox",List.of(-10,0,20,30));assertFalse(TableStructure.analyze("测试甲",List.of("name","id","role"),f.cells,sources(f)).valid());}}
    @Test void keyValueBindingRequiresOnePersonAndCannotInheritAnotherName(){var f=fixture();var extra=new LinkedHashMap<>(f.cells.get(1));extra.put("cellId","second-name");extra.put("spanId","second-name");extra.put("column",3);extra.put("headerCellIds",List.of("name-label"));var label=new LinkedHashMap<>(f.cells.get(0));label.put("cellId","second-label");label.put("spanId","second-label");label.put("column",2);extra.put("headerCellIds",List.of("second-label"));f.cells.add(label);f.cells.add(extra);assertEquals("STRUCTURE_KEY_VALUE_OWNER_AMBIGUOUS",TableStructure.analyze("测试甲",List.of("name","id","role"),f.cells,sources(f)).issue());}
    @Test void keyValueNameLabelCannotLeakIntoUnlabelledRowsBelow(){var f=fixture();f.cells.add(cell(f.corpus,"school-label",3,1,"毕业学校",false,List.of(),List.of("毕业学校")));f.cells.add(cell(f.corpus,"school",3,2,"测试学院",false,List.of(),List.of("测试学院")));var result=TableStructure.analyze("测试甲",List.of("name","id","role"),f.cells,sources(f));assertTrue(result.valid(),result.toString());assertEquals(1,result.rows().size());assertTrue(result.rows().get(0).strongIdentity());}
}
